import sys

def main():
    s = sys.stdin.read().split()[0]
    st = []
    for ch in s:
        st.append(ch)
        if ch == 'S' and len(st) >= 3 and st[-2] == 'W' and st[-3] == 'A':
            del st[-3:]
    print(''.join(st) if st else '-1')

